  /* e7-question */ (function (a) { for (var k in a) E[k] = a[k]; })({"【標準】（　）に入る疑問詞はどれ？\n（　） is that boy? — He is my brother.": "答え：Who。疑問詞：What＝何、Where＝どこ、When＝いつ、Who＝だれ、Whose＝だれの、Which＝どちら、Why＝なぜ、How＝どのように。答えの 内容から 選ぶ。", "【基礎】「なに」とたずねるときに使う疑問詞はどれ？": "what。疑問詞：What＝何、Where＝どこ、When＝いつ、Who＝だれ、Whose＝だれの、Which＝どちら、Why＝なぜ、How＝どのように。答えの 内容から 選ぶ。", "【基礎】「どちら・どれ」とたずねるときに使う疑問詞はどれ？": "which。疑問詞：What＝何、Where＝どこ、When＝いつ、Who＝だれ、Whose＝だれの、Which＝どちら、Why＝なぜ、How＝どのように。答えの 内容から 選ぶ。", "【標準】（　）に入る疑問詞はどれ？\n（　） do you live? — I live in Nagoya.": "答え：Where。疑問詞：What＝何、Where＝どこ、When＝いつ、Who＝だれ、Whose＝だれの、Which＝どちら、Why＝なぜ、How＝どのように。答えの 内容から 選ぶ。", "【基礎】「いつ」とたずねるときに使う疑問詞はどれ？": "when。疑問詞：What＝何、Where＝どこ、When＝いつ、Who＝だれ、Whose＝だれの、Which＝どちら、Why＝なぜ、How＝どのように。答えの 内容から 選ぶ。", "【基礎】「だれ」とたずねるときに使う疑問詞はどれ？": "who。疑問詞：What＝何、Where＝どこ、When＝いつ、Who＝だれ、Whose＝だれの、Which＝どちら、Why＝なぜ、How＝どのように。答えの 内容から 選ぶ。", "【標準】（　）に入る疑問詞はどれ？\n（　） is your birthday? — It's May 5th.": "答え：When。疑問詞：What＝何、Where＝どこ、When＝いつ、Who＝だれ、Whose＝だれの、Which＝どちら、Why＝なぜ、How＝どのように。答えの 内容から 選ぶ。", "【標準】（　）に入る疑問詞はどれ？\n（　） bag is this? — It's Ken's.": "答え：Whose。疑問詞：What＝何、Where＝どこ、When＝いつ、Who＝だれ、Whose＝だれの、Which＝どちら、Why＝なぜ、How＝どのように。答えの 内容から 選ぶ。", "【標準】（　）に入る疑問詞はどれ？\n（　） time do you get up? — At six.": "答え：What。疑問詞：What＝何、Where＝どこ、When＝いつ、Who＝だれ、Whose＝だれの、Which＝どちら、Why＝なぜ、How＝どのように。答えの 内容から 選ぶ。", "【発展】What time is it now? への答えとして正しいのは？": "It's ten thirty.疑問詞（What・Where・Who・How など）が 何を たずねているかに 合わせて 答える。", "【標準】（　）に入る疑問詞はどれ？\n（　） many CDs do you have? — I have ten.": "答え：How。疑問詞：What＝何、Where＝どこ、When＝いつ、Who＝だれ、Whose＝だれの、Which＝どちら、Why＝なぜ、How＝どのように。答えの 内容から 選ぶ。", "【発展】How many brothers do you have? への答えとして正しいのは？": "I have two.疑問詞（What・Where・Who・How など）が 何を たずねているかに 合わせて 答える。", "【基礎】「だれの」とたずねるときに使う疑問詞はどれ？": "whose。疑問詞：What＝何、Where＝どこ、When＝いつ、Who＝だれ、Whose＝だれの、Which＝どちら、Why＝なぜ、How＝どのように。答えの 内容から 選ぶ。", "【発展】Whose bike is that? への答えとして正しいのは？": "It's my brother's.疑問詞（What・Where・Who・How など）が 何を たずねているかに 合わせて 答える。", "【基礎】「どこ」とたずねるときに使う疑問詞はどれ？": "where。疑問詞：What＝何、Where＝どこ、When＝いつ、Who＝だれ、Whose＝だれの、Which＝どちら、Why＝なぜ、How＝どのように。答えの 内容から 選ぶ。", "【発展】Where does Ken live? への答えとして正しいのは？": "He lives in Osaka.疑問詞（What・Where・Who・How など）が 何を たずねているかに 合わせて 答える。"});
  /* e7-can */ (function (a) { for (var k in a) E[k] = a[k]; })({"【基礎】「わたしは速く走ることができます。」\nI can （　）.": "答え：run fast。助動詞や 不定詞の to の 後ろは 動詞の 原形（be動詞は be）。", "【発展】「ここで英語を話しなさい。」を英語にすると？": "Speak English here.主語→動詞→目的語→場所→時の 語順。", "【標準】Can Ken cook? に「はい」と答えるときは？": "Yes, he can.疑問文の 最初の 語（Is・Are・Do・Does・Did・Can など）を 使って 答え、主語は 代名詞（he・she・it・they）に する。", "【基礎】「わたしはじょうずに歌うことができます。」\nI can （　）.": "答え：sing well。助動詞や 不定詞の to の 後ろは 動詞の 原形（be動詞は be）。", "【基礎】「わたしは料理することができます。」\nI can （　）.": "答え：cook。助動詞や 不定詞の to の 後ろは 動詞の 原形（be動詞は be）。", "【基礎】「彼は速く走ることができます。」を英語にすると？": "He can run fast.主語→動詞→目的語→場所→時の 語順。", "【発展】「サッカーをしましょう。」\n（　） play soccer.": "答え：Let's。前後の 語と 意味の つながりから 考える。", "【標準】「わたしはスキーができません。」\nI （　） ski.": "答え：can't。助動詞は 動詞の 前に 置き、後ろの 動詞は 原形。", "【発展】「窓を開けなさい。」を英語にすると？": "Open the window.主語→動詞→目的語→場所→時の 語順。", "【標準】「あなたはギターを弾けますか。」\n（　） you play the guitar?": "答え：Can。助動詞は 動詞の 前に 置き、後ろの 動詞は 原形。", "【標準】Can you help me? はどんな意味？": "手伝ってくれませんか（お願い）。主語と 動詞を 先に 見つけて 訳すと わかりやすい。", "【基礎】「わたしは泳ぐことができます。」\nI can （　）.": "答え：swim。助動詞や 不定詞の to の 後ろは 動詞の 原形（be動詞は be）。", "【発展】「ここで走ってはいけません。」\n（　） run here.": "答え：Don't。一般動詞の 疑問文・否定文は do／does（三人称単数）／did（過去）を 使い、動詞は 原形に もどす。", "【基礎】「わたしはギターを弾くことができます。」\nI can （　）.": "答え：play the guitar。助動詞や 不定詞の to の 後ろは 動詞の 原形（be動詞は be）。", "【発展】「手を洗いなさい。」を英語にすると？": "Wash your hands.主語→動詞→目的語→場所→時の 語順。"});
  /* e7-ing */ (function (a) { for (var k in a) E[k] = a[k]; })({"【標準】（　）に入る語はどれ？\nHe is （　） in the park now.": "答え：running。進行形は be動詞＋動詞の ing形。「〜している（いた）ところ」。", "【基礎】「わたしは今、テレビを見ています。」\nI （　） TV now.": "答え：am watching。進行形は be動詞＋動詞の ing形。「〜している（いた）ところ」。", "【基礎】「make」の ing形はどれ？": "make → making。e で 終わる 語は e を とって ing。", "【標準】「あなたは今、勉強していますか。」\n（　） you studying now?": "答え：Are。現在の be動詞は 主語で 決まる：I→am、he・she・it・単数（1人・1つ）→is、you・複数→are。", "【基礎】「write」の ing形はどれ？": "write → writing。e で 終わる 語は e を とって ing。", "【標準】「彼女は今、歌っていません。」\nShe （　） not singing now.": "答え：is。現在の be動詞は 主語で 決まる：I→am、he・she・it・単数（1人・1つ）→is、you・複数→are。", "【発展】What are you doing? への答えとして正しいのは？": "I'm doing my homework.疑問詞（What・Where・Who・How など）が 何を たずねているかに 合わせて 答える。", "【標準】「彼女は今、本を読んでいます。」を英語にすると？": "She is reading a book now.進行形は be動詞＋動詞の ing形。「〜している（いた）ところ」。", "【基礎】「run」の ing形はどれ？": "run → running。短母音＋子音で 終わる 語は 最後の 字を 重ねて ing。", "【基礎】「play」の ing形はどれ？": "play → playing。そのまま ing を つける。", "【発展】（　）に入る語はどれ？\nKen （　） soccer now.": "答え：is playing。進行形は be動詞＋動詞の ing形。「〜している（いた）ところ」。", "【基礎】「swim」の ing形はどれ？": "swim → swimming。短母音＋子音で 終わる 語は 最後の 字を 重ねて ing。", "【基礎】「sit」の ing形はどれ？": "sit → sitting。短母音＋子音で 終わる 語は 最後の 字を 重ねて ing。", "【基礎】「use」の ing形はどれ？": "use → using。e で 終わる 語は e を とって ing。", "【基礎】「study」の ing形はどれ？": "study → studying。そのまま ing を つける。"});
  /* e7-past */ (function (a) { for (var k in a) E[k] = a[k]; })({"【標準】「わたしは昨日、テニスをしませんでした。」\nI （　） play tennis yesterday.": "答え：didn't。一般動詞の 疑問文・否定文は do／does（三人称単数）／did（過去）を 使い、動詞は 原形に もどす。", "【発展】（　）に入る語はどれ？（否定文では動詞は原形！）\nShe didn’t （　） breakfast this morning.": "答え：eat。前後の 語と 意味の つながりから 考える。", "【標準】「わたしは昨夜、テレビを見ました。」\nI （　） TV last night.": "答え：watched。前後の 語と 意味の つながりから 考える。", "【基礎】「watch」の過去形はどれ？": "watch → watched。規則動詞は ed を つける。", "【発展】（　）に入る語はどれ？（疑問文では動詞は原形！）\nDid you （　） the movie yesterday?": "答え：see。前後の 語と 意味の つながりから 考える。", "【標準】「彼は昨日、学校へ行きました。」\nHe （　） to school yesterday.": "答え：went。前後の 語と 意味の つながりから 考える。", "【基礎】「play」の過去形はどれ？": "play → played。規則動詞は ed を つける。", "【基礎】「have」の過去形はどれ？": "have → had。不規則動詞は 形が 変わるので 1つずつ 覚える。", "【標準】Did you see the movie? に「はい」と答えるときは？": "Yes, I did.疑問文の 最初の 語（Is・Are・Do・Does・Did・Can など）を 使って 答え、主語は 代名詞（he・she・it・they）に する。", "【基礎】「get」の過去形はどれ？": "get → got。不規則動詞は 形が 変わるので 1つずつ 覚える。", "【発展】「わたしは先週、京都へ行きました。」を英語にすると？": "I went to Kyoto last week.不定詞 to＋動詞の 原形。「〜すること」「〜するために」「〜するための」の 意味。", "【基礎】「run」の過去形はどれ？": "run → ran。不規則動詞は 形が 変わるので 1つずつ 覚える。", "【基礎】「stop」の過去形はどれ？": "stop → stopped。規則動詞は ed を つける。", "【基礎】「study」の過去形はどれ？": "study → studied。子音＋y で 終わる 語は y を i に して ed。", "【基礎】「buy」の過去形はどれ？": "buy → bought。不規則動詞は 形が 変わるので 1つずつ 覚える。", "【基礎】「go」の過去形はどれ？": "go → went。不規則動詞は 形が 変わるので 1つずつ 覚える。", "【基礎】「write」の過去形はどれ？": "write → wrote。不規則動詞は 形が 変わるので 1つずつ 覚える。", "【基礎】「eat」の過去形はどれ？": "eat → ate。不規則動詞は 形が 変わるので 1つずつ 覚える。", "【基礎】「make」の過去形はどれ？": "make → made。不規則動詞は 形が 変わるので 1つずつ 覚える。", "【基礎】「see」の過去形はどれ？": "see → saw。不規則動詞は 形が 変わるので 1つずつ 覚える。", "【基礎】「come」の過去形はどれ？": "come → came。不規則動詞は 形が 変わるので 1つずつ 覚える。"});
