  /* j9-yomi */ (function (a) { for (var k in a) E[k] = a[k]; })({"【基礎】「遮る」の読みはどれ？": "「遮る」＝さえぎる。送りがなの ある 言葉は 訓読み。送りがなが 読みの 手がかり。", "【発展】「疾病」の読みはどれ？": "「疾病」＝しっぺい。熟語は ふつう 音読み＋音読み。", "【発展】「貪欲」の読みはどれ？": "「貪欲」＝どんよく。熟語は ふつう 音読み＋音読み。", "【標準】「庶民」の読みはどれ？": "「庶民」＝しょみん。熟語は ふつう 音読み＋音読み。", "【標準】「進捗」の読みはどれ？": "「進捗」＝しんちょく。熟語は ふつう 音読み＋音読み。", "【基礎】「慕う」の読みはどれ？": "「慕う」＝したう。送りがなの ある 言葉は 訓読み。送りがなが 読みの 手がかり。", "【基礎】「促す」の読みはどれ？": "「促す」＝うながす。送りがなの ある 言葉は 訓読み。送りがなが 読みの 手がかり。", "【標準】「折衷」の読みはどれ？": "「折衷」＝せっちゅう。熟語は ふつう 音読み＋音読み。", "【標準】「遂行」の読みはどれ？": "「遂行」＝すいこう。熟語は ふつう 音読み＋音読み。", "【発展】「委ねる」の読みはどれ？": "「委ねる」＝ゆだねる。送りがなの ある 言葉は 訓読み。送りがなが 読みの 手がかり。", "【標準】「措置」の読みはどれ？": "「措置」＝そち。熟語は ふつう 音読み＋音読み。", "【発展】「流布」の読みはどれ？": "「流布」＝るふ。熟語は ふつう 音読み＋音読み。", "【基礎】「滑らか」の読みはどれ？": "「滑らか」＝なめらか。送りがなの ある 言葉は 訓読み。送りがなが 読みの 手がかり。", "【基礎】「繕う」の読みはどれ？": "「繕う」＝つくろう。送りがなの ある 言葉は 訓読み。送りがなが 読みの 手がかり。", "【基礎】「担う」の読みはどれ？": "「担う」＝になう。送りがなの ある 言葉は 訓読み。送りがなが 読みの 手がかり。", "【基礎】「催す」の読みはどれ？": "「催す」＝もよおす。送りがなの ある 言葉は 訓読み。送りがなが 読みの 手がかり。", "【発展】「体裁」の読みはどれ？": "「体裁」＝ていさい。熟語は ふつう 音読み＋音読み。", "【標準】「憂慮」の読みはどれ？": "「憂慮」＝ゆうりょ。熟語は ふつう 音読み＋音読み。", "【標準】「払拭」の読みはどれ？": "「払拭」＝ふっしょく。熟語は ふつう 音読み＋音読み。", "【標準】「示唆」の読みはどれ？": "「示唆」＝しさ。熟語は ふつう 音読み＋音読み。", "【発展】「相殺」の読みはどれ？": "「相殺」＝そうさい。熟語は ふつう 音読み＋音読み。", "【発展】「帰依」の読みはどれ？": "「帰依」＝きえ。熟語は ふつう 音読み＋音読み。", "【基礎】「憩う」の読みはどれ？": "「憩う」＝いこう。送りがなの ある 言葉は 訓読み。送りがなが 読みの 手がかり。"});
  /* j8-bunpo */ (function (a) { for (var k in a) E[k] = a[k]; })({"「走りたい」の「たい」の 意味は？": "「たい」は 希望の 助動詞。「〜したい」。", "「まるで 夢の ようだ。」の「ようだ」の 意味は？": "「まるで〜ようだ」は たとえ（比喩）。「どうやら〜ようだ」なら 推定。", "「弟に 片づけさせる。」の「させる」の 意味は？": "「させる」は 人に させる 使役の 助動詞。", "「行くまい」の「まい」の 意味は？": "「まい」は 打ち消しの 意志（〜しないつもりだ）や 打ち消しの 推量。", "「書く」の 活用の 種類は？（ない を つけると「書か」）": "「ない」を つけて ア段（書か）に なるのが 五段活用。", "「起きる」の 活用の 種類は？（ない を つけると「起き」）": "「ない」を つけて イ段（起き）に なるのが 上一段活用。", "「来る」の 活用の 種類は？": "「来る」だけが カ行変格活用。", "「勉強する」の 活用の 種類は？": "「する」「〜する」は サ行変格活用。", "「書けば」の「書け」の 活用形は？": "「ば」に 続く 形が 仮定形。", "「書きます」の「書き」の 活用形は？": "「ます」に 続く 形が 連用形。", "「先生に ほめられる。」の「られる」の 意味は？": "「られる」が 人から される 意味なら 受け身。可能・自発・尊敬との 区別は 言いかえて 確かめる。", "「食べる」の 活用の 種類は？（ない を つけると「食べ」）": "「ない」を つけて エ段（食べ）に なるのが 下一段活用。", "「書かない」の「書か」の 活用形は？": "「ない」に 続く 形が 未然形。", "「明日は 雨らしい。」の「らしい」の 意味は？": "「らしい」は 根拠の ある 推定（〜と 思われる）。", "「朝 六時に 起きられる。」の「られる」の 意味は？": "「〜することが できる」と 言いかえられるので 可能。"});
  /* j8-koten */ (function (a) { for (var k in a) E[k] = a[k]; })({"「つれづれなるままに」で 始まる 作品は？": "「つれづれなるままに」は 兼好法師の 徒然草の 書き出し。", "古文の「をかし」の 意味で 合うのは？": "古文の「をかし」は 趣が ある・おもしろい。枕草子に 多い。", "古文の「つきづきし」の 意味は？": "「つきづきし」は 似つかわしい・ふさわしい。", "「枕草子」の ジャンルは？": "枕草子は 見聞きした ことや 感想を 書いた 随筆。", "「平家物語」を 語り伝えた 人々は？": "琵琶法師が 琵琶を ひきながら 平家物語を 語り伝えた。", "「平家物語」の ジャンルは？": "平家物語は 戦いを えがいた 軍記物語。", "「祇園精舎の 鐘の 声、諸行無常の 響き あり。」で 始まる 作品は？": "「祇園精舎の 鐘の声」は 平家物語の 書き出し。", "「枕草子」の 作者は？": "枕草子の 作者は 清少納言。", "「徒然草」の 作者は？": "徒然草の 作者は 兼好法師（吉田兼好）。", "「春は あけぼの。」で 始まる 作品は？": "「春は あけぼの」は 枕草子の 書き出し。", "「諸行無常」の 意味に 近いのは？": "諸行無常＝この世の すべての ものは 移り変わる。平家物語の テーマ。"});
  /* j9-bunpo */ (function (a) { for (var k in a) E[k] = a[k]; })({"「言う」の 尊敬語は？": "「言う」の 尊敬語は「おっしゃる」。謙譲語は「申す」。", "「先生が 申された。」の 正しい 直しは？": "「申す」は 謙譲語なので 先生には 使わない。尊敬語「おっしゃる」に 直す。", "「お金が ない。」の「ない」は？": "「ない」が「存在しない」の 意味で 単独で 使えるので 形容詞。「ぬ」に 言いかえられない。", "「学校で 学ぶ。」の「で」は？": "「で」は 場所を 示す 格助詞。", "「もらう」の 謙譲語は？": "「もらう」の 謙譲語は「いただく」。", "「静かで きれいだ。」の「で」は？": "「静かだ」の 連用形「静かで」の 一部なので 形容動詞の 活用語尾。", "「雨が 降らない。」の「ない」は？": "「降らぬ」と「ぬ」に 言いかえられるので 打ち消しの 助動詞。", "「ぼくの 書いた 絵」の「の」の はたらきは？": "「の」が「が」に 言いかえられる（ぼくが 書いた）ので 主語を 示す。", "「先生が いらっしゃる。」の 敬語の 種類は？": "「いらっしゃる」は 先生（相手）の 動作を 高める 尊敬語。", "「食べる」の 尊敬語は？": "「食べる」の 尊敬語は「召し上がる」。謙譲語は「いただく」。", "「見る」の 謙譲語は？": "「見る」の 謙譲語は「拝見する」。尊敬語は「ご覧に なる」。", "「私が 先生の お宅に うかがう。」の 敬語の 種類は？": "「うかがう」は 自分の 動作を へりくだる 謙譲語。"});
